def two_advisory_profile(raw):
    row=CONSOLIDATED_PROFILE
    if hashlib.sha256(raw.replace(b"\r\n",b"\n")).hexdigest()!=row["after_sha256"]:return raw
    return authenticated_profile_preimage(row)

def single_advisory_profile(raw):
    raw=two_advisory_profile(raw)
    row=SINGLE_ADVISORY_PROFILE
    if hashlib.sha256(raw.replace(b"\r\n",b"\n")).hexdigest()!=row["after_sha256"]:return raw
    return authenticated_profile_preimage(row)

def authenticated_profile_preimage(row):
    z=zlib.decompressobj()
    value=z.decompress(base64.b85decode(row["compressed"]),row["bytes"]+1)
    blob=hashlib.sha1(b"blob "+str(len(value)).encode()+b"\0"+value).hexdigest()
    if not (z.eof and not z.unused_data and len(value)==row["bytes"] and hashlib.sha256(value).hexdigest()==row["before_sha256"] and blob==row["before_git_blob"]):
        raise ValueError("CI_FIXTURE_AUTHENTICATED_PROFILE_PREDECESSOR")
    return value

def original_source(relative,raw):
    row=RECORDS.get(relative)
    exact_single = relative==PROFILE and hashlib.sha256(raw.replace(b'\r\n',b'\n')).hexdigest() in {SINGLE_ADVISORY_PROFILE['before_sha256'],CONSOLIDATED_PROFILE['before_sha256']}
    if row is None or (not exact_single and hashlib.sha256(raw.replace(b'\r\n',b'\n')).hexdigest()!=row['after_sha256']):
        return raw
    z=zlib.decompressobj()
    value=z.decompress(base64.b85decode(row['compressed']),row['bytes']+1)
    blob=hashlib.sha1(b'blob '+str(len(value)).encode()+b'\0'+value).hexdigest()
    if not (z.eof and not z.unused_data and len(value)==row['bytes']
            and hashlib.sha256(value).hexdigest()==row['before_sha256'] and blob==row['before_git_blob']):
        raise ValueError('CI_FIXTURE_AUTHENTICATED_PREDECESSOR_SOURCE')
    return value

