def reader_source(relative,current,nodeid):
    record=EXACT_READER_INPUTS.get(nodeid)
    normalized=current.replace(b'\r\n',b'\n')
    if (record is None or relative!=record['path']
        or hashlib.sha256(normalized).hexdigest()!=record['current_sha256']):
        return original_source(relative,current)
    with (ROOT/record['binding']).open('rb') as stream:
        binding_raw=stream.read().replace(b'\r\n',b'\n')
    if hashlib.sha256(binding_raw).hexdigest()!=record['binding_sha256']:
        raise ValueError('HISTORICAL_READER_BINDING_CHANGED')
    contract=__import__('json').loads(binding_raw)['source_reconstructions'][relative]
    image=zlib.decompress(base64.b85decode(record['compressed']))
    if (len(image)!=record['input_bytes']
        or hashlib.sha256(image).hexdigest()!=record['input_sha256']
        or hashlib.sha1(b'blob '+str(len(image)).encode()+b'\0'+image).hexdigest()!=record['input_git_blob']
        or contract['after_sha256']!=record['input_sha256']):
        raise ValueError('HISTORICAL_READER_INPUT_CHANGED')
    return image


def _install_selected_predecessor_sources(request,patch):
    module=request.module
    name=module.__name__.rsplit('.',1)[-1]
    if name not in CONSUMERS|GUARD_CONSUMERS|PROFILE_CONSUMERS:return False
    if name=='test_ci_fixture_stability_scope' and not (single_profile_selected(request) or two_profile_selected(request)):return False
    try:
        relative=Path(module.__file__).resolve().relative_to(ROOT/'tests')
        if relative.as_posix()!=name+'.py':return False
    except (ValueError,AttributeError):return False
    read=Path.read_bytes
    native_open=Path.open
    node=getattr(getattr(request,'node',None),'originalname',None) or getattr(getattr(request,'node',None),'name','').split('[',1)[0]
    reader_node=name+'::'+node
    open_record_view=(reader_node==
        'test_ncaaf_reviewed_target_scope::test_current_sources_have_exact_preimages_and_unknown_bytes_stay_unknown')
    profile_view = historical_profile_selected(request)
    single_view = single_profile_selected(request)
    two_view = two_profile_selected(request)
    install_profile_helper_preimages(request, patch)
    from tests.historical_scope_input_boundary import canonical_guard
    loader=canonical_guard()._ci_fixture_module
    def source_open(path,mode='r',*args,**kwargs):
        if open_record_view and mode in ('r','rb'):
            try: relative=path.resolve().relative_to(ROOT).as_posix()
            except ValueError: relative=None
            if relative in RECORDS and relative!=PROFILE:
                with native_open(path,'rb') as stream: raw=stream.read()
                value=original_source(relative,raw)
                return io.BytesIO(value) if mode=='rb' else io.StringIO(value.decode(kwargs.get('encoding') or 'utf-8'))
        if (profile_view or single_view or two_view) and path.resolve()==(ROOT/PROFILE).resolve() and mode in ('r','rb'):
            with native_open(path,'rb') as stream: raw=stream.read()
            value=two_advisory_profile(raw) if two_view else single_advisory_profile(raw) if single_view else original_source(PROFILE,raw)
            import locale
            encoding=kwargs.get('encoding') or 'utf-8'
            if encoding=='locale':encoding=locale.getencoding()
            return io.BytesIO(value) if mode=='rb' else io.StringIO(value.decode(encoding))
        # Only the immutable guard source for an explicit historical test reader.
        if name not in GUARD_CONSUMERS or path.resolve()!=(ROOT/'scripts/check_launch_change_scope.py').resolve() or mode not in ('r','rb'):
            return native_open(path,mode,*args,**kwargs)
        with native_open(path,'rb') as stream:raw=stream.read()
        try:
            module,binding=loader()
            value=module.previous_guard(raw.replace(b'\r\n',b'\n'),binding)
        except (OSError,ValueError,KeyError,TypeError):value=raw
        return io.BytesIO(value) if mode=='rb' else io.StringIO(value.decode(kwargs.get('encoding') or 'utf-8'))
    patch.setattr(Path,'open',source_open)
    def historical(path):
        raw=read(path)
        try:relative=path.resolve().relative_to(ROOT).as_posix()
        except ValueError:return raw
        if relative==PROFILE and two_view:return two_advisory_profile(raw)
        if relative==PROFILE and single_view:return single_advisory_profile(raw)
        if relative==PROFILE and not profile_view:return raw
        return reader_source(relative,raw,reader_node)
    patch.setattr(Path,'read_bytes',historical)
    return True


# Historical input selectors are exact module/test names, never current gates.
PROFILE_ALL_HISTORICAL = frozenset({
    'test_ci_scheduling_scope','test_ci_six_shards',
    'test_football_document_ci_closure','test_football_document_ci_performance',
    'test_ncaaf_socket_ci_costs','test_ncaaf_staged_ci_capacity',
    'test_nfl_listing_cost_scope','test_nfl_listing_immutable_scope',
    'test_nfl_listing_metadata_scope','test_nfl_pdf_ci_scope','test_nfl_pdf_timing_costs',
})
PROFILE_EXACT_TESTS = {
    'test_ci_timing_profile': frozenset(['test_revision_provenance_and_honest_incomplete_observations']),
    'test_football_document_ci_closure_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_football_document_ci_performance_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_football_document_six_capacity_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_ncaaf_chronology_capacity': frozenset(['test_current_eleven_way_gate_preserves_profile_limits_and_history', 'test_historical_input_projection_is_exact_and_restores_global_state']),
    'test_ncaaf_reviewed_target_scope': frozenset(['test_current_sources_have_exact_preimages_and_unknown_bytes_stay_unknown']),
    'test_ncaaf_reviewed_target_timing': frozenset(['test_direct_historical_profile_readers_receive_only_exact_prior_bytes', 'test_five_live_costs_preserve_historical_measurement_meanings']),
    'test_ncaaf_socket_ci_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_ncaaf_staged_capacity_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_nfl_pdf_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
    'test_nfl_pdf_timing_scope': frozenset(['test_exact_predecessor_source_reconstruction_and_unknown_edits']),
}
PROFILE_CONSUMERS = PROFILE_ALL_HISTORICAL | frozenset(PROFILE_EXACT_TESTS) | {'test_ci_fixture_stability_scope'}

def single_profile_selected(request):
    name=request.module.__name__.rsplit('.',1)[-1]
    node=getattr(getattr(request,'node',None),'originalname',None) or getattr(getattr(request,'node',None),'name','').split('[',1)[0]
    return name=='test_ci_fixture_stability_scope' and node=='test_single_advisory_amendment_preserves_all_other_rows_and_metadata'

def two_profile_selected(request):
    name=request.module.__name__.rsplit('.',1)[-1]
    node=getattr(getattr(request,'node',None),'originalname',None) or getattr(getattr(request,'node',None),'name','').split('[',1)[0]
    return name=='test_ci_fixture_stability_scope' and node in {
        'test_second_advisory_amendment_retains_exact_single_entry_predecessor',
        'test_second_advisory_preimage_is_narrow_authenticated_and_restored'}

def historical_profile_selected(request):
    name=request.module.__name__.rsplit('.',1)[-1]
    node=getattr(getattr(request,'node',None),'originalname',None) or getattr(getattr(request,'node',None),'name','').split('[',1)[0]
    return name in PROFILE_ALL_HISTORICAL or node in PROFILE_EXACT_TESTS.get(name,())

def install_profile_helper_preimages(request,patch):
    # Mixed current/historical tests keep live reads. Only exact immutable input
    # to the existing frozen reconstruction helpers is peeled before their hashes.
    if request.module.__name__.rsplit('.',1)[-1] not in PROFILE_CONSUMERS:return
    from tests import ncaaf_staged_capacity_fixtures as fixtures
    for name in ('reviewed_target_three_cost_profile','reviewed_target_predecessor_profile'):
        previous=getattr(fixtures,name)
        def exact(source,_previous=previous):
            return _previous(original_source(PROFILE,source))
        patch.setattr(fixtures,name,exact)


def install_exact_predecessor_sources(request,patch):
    from tests.historical_scope_input_boundary import resolve_context,Role,owned_api_patch
    plan=resolve_context(request)
    if plan.role is not Role.HISTORICAL:return False
    return _install_selected_predecessor_sources(request,owned_api_patch(patch,plan))
